// n8n Code node: Validate Douyin Publish Start Params
// Expected query: ?task_id=<video_topics.id>&token=<review_token>

const source = $json || {};
const query = source.query || source.params || source;

const taskId = String(query.task_id || query.id || '').trim();
const token = String(query.token || '').trim();

if (!taskId) {
  throw new Error('缺少 task_id 参数');
}

if (!token) {
  throw new Error('缺少 token 参数');
}

return [
  {
    json: {
      task_id: taskId,
      token,
      platform: 'douyin',
      received_at: new Date().toISOString(),
    },
  },
];

// n8n Code node: Build Douyin Package Request
// Input: one row from video_publish_jobs.
// Output: JSON body for publish-helper /package/douyin.

function env(name, fallback = '') {
  try {
    if (typeof $env !== 'undefined' && $env[name]) return $env[name];
  } catch (error) {}
  return fallback;
}

function normalizeHashtags(value) {
  if (!value) return [];
  if (Array.isArray(value)) return value.map(String).map(s => s.trim()).filter(Boolean);
  return String(value)
    .split(/[，,\s]+/)
    .map(s => s.trim())
    .filter(Boolean)
    .map(s => s.startsWith('#') ? s : `#${s}`)
    .slice(0, 8);
}

const inputItems = typeof items !== 'undefined' ? items : $input.all();
const publicFileBaseUrl = env('PUBLIC_FILE_BASE_URL', '').replace(/\/$/, '');

return inputItems.map(item => {
  const row = item.json;
  if (row.success === false || row.success === 'false') {
    throw new Error(`无法启动抖音发布任务：${row.result_code || 'UNKNOWN'}`);
  }

  const hashtags = normalizeHashtags(row.hashtags);
  const title = row.title || '抖音待发布视频';

  let caption = row.caption || '';
  if (!caption.trim()) {
    caption = `${title}\n\n${hashtags.join(' ')}`.trim();
  }

  return {
    json: {
      job_id: String(row.id),
      video_topic_id: row.video_topic_id,
      title,
      caption,
      hashtags,
      video_path: row.video_path,
      cover_path: row.cover_path || '',
      manual_confirm_token: row.manual_confirm_token,
      public_file_base_url: publicFileBaseUrl
    }
  };
});

// n8n Code node: Build ServerChan Message
// Input: publish-helper package response.
// Output: ServerChan title/desp and manual confirmation links.

function env(name, fallback = '') {
  // n8n Code 节点中通常可以通过 $env 读取环境变量。
  try {
    if (typeof $env !== 'undefined' && $env[name]) return $env[name];
  } catch (e) {}
  return fallback;
}

const publicN8nBase = env('PUBLIC_N8N_BASE_URL', 'http://localhost:5678').replace(/\/$/, '');
const serverchanSendKey = env('SERVERCHAN_SENDKEY', '').trim();
const serverchanUrl = serverchanSendKey ? `https://sctapi.ftqq.com/${serverchanSendKey}.send` : '';

const inputItems = typeof items !== 'undefined' ? items : $input.all();

return inputItems.map(item => {
  const data = item.json;
  const rawJobId = data.job_id || data.id;
  const jobId = encodeURIComponent(rawJobId);
  const token = encodeURIComponent(data.manual_confirm_token || data.token || '');

  const doneUrl = `${publicN8nBase}/webhook/douyin-manual-publish-action?action=published&job_id=${jobId}&token=${token}`;
  const skipUrl = `${publicN8nBase}/webhook/douyin-manual-publish-action?action=skip&job_id=${jobId}&token=${token}`;
  const downloadPageUrl = data.download_page_url || data.video_url || '';
  const videoDownloadUrl = data.video_download_url || data.video_url || '';

  const title = `🎬 抖音视频待发布：${data.title || '未命名视频'}`;
  const hashtags = Array.isArray(data.hashtags) ? data.hashtags.join(' ') : (data.hashtags || '');

  const desp = [
    '# 🎬 抖音视频待发布',
    '',
    `**标题：** ${data.title || ''}`,
    '',
    '## 文案',
    '',
    data.caption || '',
    '',
    '## 话题',
    '',
    hashtags,
    '',
    '## 下载',
    '',
    downloadPageUrl ? `- [打开下载页面](${downloadPageUrl})` : '- 下载页面缺失',
    videoDownloadUrl ? `- [直接下载视频 final.mp4](${videoDownloadUrl})` : '- 视频链接缺失',
    data.cover_url ? `- [下载封面 cover.png](${data.cover_url})` : '- 封面链接缺失',
    data.caption_url ? `- [下载文案 caption.txt](${data.caption_url})` : '',
    '',
    '## 操作步骤',
    '',
    '1. 在手机上打开下载页面，先预览确认视频。',
    '2. 复制上面的文案和话题。',
    '3. 打开抖音 App，手动上传并确认发布。',
    '4. 发布完成后点击下面的“我已发布”。',
    '',
    '> 微信内如果只能播放不能保存，请点右上角选择“在浏览器打开”，再点下载视频文件。',
    '',
    `✅ [我已发布](${doneUrl})`,
    '',
    `⏸ [暂不发布](${skipUrl})`
  ].filter(Boolean).join('\n');

  return {
    json: {
      ...data,
      job_id: String(rawJobId),
      manual_published_url: doneUrl,
      manual_skip_url: skipUrl,
      serverchan_title: title,
      serverchan_desp: desp,
      remind_message: desp,
      serverchan_url: serverchanUrl || 'http://publish-helper:8010/serverchan-skip',
      serverchan_enabled: Boolean(serverchanUrl)
    }
  };
});

// n8n Code node: Normalize ServerChan Response

const inputItems = typeof items !== 'undefined' ? items : $input.all();

return inputItems.map(item => {
  const res = item.json;
  let remindMessage = '';
  let serverchanEnabled = true;
  try {
    const messageNode = $('代码 - 构建Server酱提醒').first().json;
    serverchanEnabled = messageNode.serverchan_enabled !== false;
    remindMessage = String(messageNode.remind_message || '');
  } catch (error) {}
  const remindMessageBase64 = Buffer.from(remindMessage, 'utf8').toString('base64');

  if (!serverchanEnabled) {
    return {
      json: {
        ...res,
        remind_status: 'SKIPPED_NO_SENDKEY',
        remind_message_base64: remindMessageBase64,
        remind_response_json: JSON.stringify(res || {}),
      },
    };
  }

  const ok = res && (res.code === 0 || res.errno === 0 || res.message === 'success' || res.data);
  return {
    json: {
      ...res,
      remind_status: ok ? 'SENT' : 'SENT_OR_UNKNOWN',
      remind_message_base64: remindMessageBase64,
      remind_response_json: JSON.stringify(res || {})
    }
  };
});

// n8n Code node: Build Douyin Publish Start Result

const row = $json || {};
const explicitSuccess = row.success;
const success = explicitSuccess === false || explicitSuccess === 'false'
  ? false
  : Boolean(row.id);

return [
  {
    json: {
      success,
      response_status_code: success ? 200 : 409,
      response_json: {
        success,
        result_code: row.result_code || (success ? 'OK' : 'INVALID_TASK_OR_TOKEN'),
        job_id: row.id || null,
        video_topic_id: row.video_topic_id || null,
        status: row.status || null,
        video_url: row.video_url || null,
        download_page_url: row.download_page_url || null,
        video_download_url: row.video_download_url || null,
        cover_url: row.cover_url || null,
        caption_url: row.caption_url || null,
        metadata_url: row.metadata_url || null,
        reminded_at: row.reminded_at || null,
      },
    },
  },
];

/**
 * n8n Code 节点：Validate Manual Publish Params
 * Webhook URL 示例：
 * /webhook/douyin-manual-publish-action?action=published&job_id=123&token=xxx
 * /webhook/douyin-manual-publish-action?action=skip&job_id=123&token=xxx&note=今天不发
 */

const query = $json.query || $json || {};
const actionRaw = String(query.action || '').toLowerCase();
const jobId = query.job_id || query.id;
const token = query.token;
const note = query.note || '';
const publishedUrl = query.published_url || '';

if (!jobId) throw new Error('缺少 job_id');
if (!token) throw new Error('缺少 token');

let actionResult;
if (['published', 'done', 'yes', 'manual_published'].includes(actionRaw)) {
  actionResult = 'MANUAL_PUBLISHED';
} else if (['skip', 'skipped', 'no', 'later', 'manual_skipped'].includes(actionRaw)) {
  actionResult = 'MANUAL_SKIPPED';
} else {
  throw new Error('action 只能是 published 或 skip');
}

return [{
  json: {
    job_id: String(jobId),
    token: String(token),
    action_result: actionResult,
    note: String(note),
    published_url: String(publishedUrl)
  }
}];

// n8n Code node: Build Manual Publish Result HTML

function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

const inputItems = typeof items !== 'undefined' ? items : $input.all();

return inputItems.map(item => {
  const row = item.json || {};
  const success = row.success === true || row.success === 'true';
  if (!success) {
    const html = `<!doctype html>
<html lang="zh-CN">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>发布确认失败</title>
  <style>
    body { font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", sans-serif; background:#f6f7f9; margin:0; padding:28px; }
    .card { max-width:720px; margin:0 auto; background:white; border-radius:18px; padding:28px; box-shadow:0 8px 30px rgba(0,0,0,.08); }
    h1 { margin:0 0 16px; color:#dc2626; }
    .row { line-height:1.9; color:#333; }
  </style>
</head>
<body>
  <div class="card">
    <h1>发布确认失败</h1>
    <div class="row"><strong>结果：</strong>${escapeHtml(row.result_code || 'UNKNOWN')}</div>
    <div class="row">常见原因：链接已过期、任务不存在，或 token 不匹配。</div>
  </div>
</body>
</html>`;
    return { json: { response_status_code: 409, response_html: html } };
  }

  const isPublished = row.status === 'MANUAL_PUBLISHED';
  const title = isPublished ? '已标记为已发布' : '已标记为暂不发布';
  const color = isPublished ? '#16a34a' : '#f59e0b';

  const html = `<!doctype html>
<html lang="zh-CN">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>${escapeHtml(title)}</title>
  <style>
    body { font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", sans-serif; background:#f6f7f9; margin:0; padding:28px; }
    .card { max-width:720px; margin:0 auto; background:white; border-radius:18px; padding:28px; box-shadow:0 8px 30px rgba(0,0,0,.08); }
    h1 { margin:0 0 16px; color:${color}; }
    .row { line-height:1.9; color:#333; }
    .muted { color:#777; font-size:14px; margin-top:16px; }
  </style>
</head>
<body>
  <div class="card">
    <h1>${escapeHtml(title)}</h1>
    <div class="row"><strong>发布任务 ID：</strong>${escapeHtml(row.id)}</div>
    <div class="row"><strong>视频任务 ID：</strong>${escapeHtml(row.video_topic_id)}</div>
    <div class="row"><strong>当前状态：</strong>${escapeHtml(row.status)}</div>
    <div class="row"><strong>标题：</strong>${escapeHtml(row.title)}</div>
    <div class="muted">你可以关闭这个页面，状态已回写到 PostgreSQL。</div>
  </div>
</body>
</html>`;

  return {
    json: {
      response_status_code: 200,
      response_html: html
    }
  };
});

